package com.aidevos.orchestrator.persistence.postgresql;
import java.util.List; import javax.sql.DataSource; import com.aidevos.orchestrator.qualitygate.*; import tools.jackson.databind.ObjectMapper;
final class PostgresQualityGateRepository implements QualityGateRepository {private static final String TYPE="quality-gate-result";private volatile PostgresDocumentStore store;private final DataSource source;private final ObjectMapper mapper;PostgresQualityGateRepository(DataSource s,ObjectMapper m){source=s;mapper=m;}private PostgresDocumentStore store(){if(store==null)synchronized(this){if(store==null)store=new PostgresDocumentStore(source,mapper);}return store;}public void save(QualityGateResult r){store().put(TYPE,r.getGateResultId(),r,r.getValidationRunId());}public QualityGateResult get(String id){return store().get(TYPE,id,QualityGateResult.class);}public List<QualityGateResult> findByValidationRunId(String id){return store().allBySecondary(TYPE,id,QualityGateResult.class);}}
